func SeparateParenGroups(paren_string string) []string {
    package main

import (
	"fmt"
	"sort"
)

func SeparateParenGroups(paren_string string) []string {
	paren_string = strings.ReplaceAll(paren_string, " ", "")
	groups := make([]string, 0)
	currentGroup := ""

	for i := 0; i < len(paren_string); i++ {
		currentGroup += string(paren_string[i])

		if IsBalanced(currentGroup) {
			groups = append(groups, currentGroup)
			currentGroup = ""
		}
	}

	return groups
}

func IsBalanced(s string) bool {
	stack := make([]rune, 0)
	opening := map[rune]rune{'(': ')'}

	for _, char := range s {
		if _, ok := opening[char]; ok {
			stack = append(stack, char)
		} else if len(stack) == 0 || opening[stack[len(stack)-1]] != char {
			return false
		} else {
			stack = stack[:len(stack)-1]
		}
	}

	return len(stack) == 0
}

