        if len(lst) == 1 {
            sorted[index] = lst[0]
            break
        }

        min, max = findMinAndMax(lst)
        sorted[index] = min
        sorted[len(lst)-1] = max

        lst = removeElement(lst, min)
        lst = removeElement(lst, max)

