    func Skjkasdkd(lst []int) int {
    isPrime := func(n int) bool {
        if n < 2 {
            return false
        }
        for i := 2; i <= int(math.Sqrt(float64(n))); i++ {
            if n%i == 0 {
                return false
            }
        }
        return true
    }

    sum := 0
    largestPrime := 0

    for _, num := range lst {
        if isPrime(num) && num > largestPrime {
            largestPrime = num
        }
    }

    if largestPrime == 0 {
        return 0
    }

    for largestPrime > 0 {
        sum += largestPrime % 10
        largestPrime /= 10
    }

    return sum
}

