    func CountUpTo(n int) []int {
    if n <= 1 {
        return []int{}
    }

    primes := []int{2}
    for num := 3; num < n; num += 2 {
        isPrime := true
        for _, prime := range primes {
            if num%prime == 0 {
                isPrime = false
                break
            }
            if prime*prime > num {
                break
            }
        }
        if isPrime {
            primes = append(primes, num)
        }
    }

    return primes
}

