    }

    minHeap := make([]int, k)
    for i := 0; i < k; i++ {
        minHeap[i] = arr[i]
    }

    for i := k/2 - 1; i >= 0; i-- {
        heapify(minHeap, k, i)
    }

    for i := k; i < len(arr); i++ {
        if arr[i] > minHeap[0] {
            minHeap[0] = arr[i]
