func Minpath(grid [][]int, k int) []int {
    func Minpath(grid [][]int, k int) []int {
    n := len(grid)

    path := make([]int, 0, k)
    visited := make([][]bool, n)
    for i := range visited {
        visited[i] = make([]bool, n)
    }

    directions := [][]int{{0, 1}, {0, -1}, {1, 0}, {-1, 0}}

    var dfs func(r, c, steps int)
    dfs = func(r, c, steps int) {
        path = append(path, grid[r][c])
        visited[r][c] = true

        if steps == k {
            return
        }

        nextR, nextC := -1, -1
        for _, dir := range directions {
            nr, nc := r+dir[0], c+dir[1]
            if nr >= 0 && nr < n && nc >= 0 && nc < n && !visited[nr][nc] && (nextR == -1 || grid[nr][nc] < grid[nextR][nextC]) {
                nextR, nextC = nr, nc
            }
        }

        if nextR != -1 {
            dfs(nextR, nextC, steps+1)
        }
    }

    for i := 0; i < n; i++ {
        for j := 0; j < n; j++ {
            dfs(i, j, 1)
        }
    }

    return path
}

