func FileNameCheck(file_name string) string {
    func FileNameCheck(file_name string) string {
    digitsCount := 0
    dotCount := 0
    letterStarted := false
    letterEnded := false
    extensionValid := false

    for i := 0; i < len(file_name); i++ {
        char := file_name[i]

        if char >= '0' && char <= '9' {
            digitsCount++
            if digitsCount > 3 {
                return "No"
            }
        } else if char == '.' {
            dotCount++
            if dotCount > 1 || !letterStarted || !extensionValid {
                return "No"
            }
            letterEnded = true
        } else if char >= 'a' && char <= 'z' || char >= 'A' && char <= 'Z' {
            if letterEnded {
                extension := file_name[i:]
                if extension == ".txt" || extension == ".exe" || extension == ".dll" {
                    extensionValid = true
                } else {
                    return "No"
                }
            } else {
                letterStarted = true
            }
        } else {
            return "No"
        }
    }

    if !letterStarted || !extensionValid {
        return "No"
    }

    return "Yes"
}

