func OrderByPoints(nums []int) []int {
	if len(nums) == 0 {
		return nums
	}

	type NumInfo struct {
		index int
		value int
		sum   int
	}

	numInfos := make([]NumInfo, len(nums))
	for i, num := range nums {
		numStr := strconv.Itoa(num)
		sum := 0
		for _, digit := range numStr {
			if digit >= '0' && digit <= '9' {
				digitVal, _ := strconv.Atoi(string(digit))
				sum += digitVal
			}
		}
		numInfos[i] = NumInfo{index: i, value: num, sum: sum}
	}

	sort.Slice(numInfos, func(i, j int) bool {
		if numInfos[i].sum == numInfos[j].sum {
			return numInfos[i].index < numInfos[j].index
		}
