func DoAlgebra(operator []string, operand []int) int {
    func DoAlgebra(operator []string, operand []int) int {
    operatorMap := map[string]int{
        "+": 1,
        "-": 2,
        "*": 3,
        "//": 4,
        "**": 5,
    }

    precedence := func(op string) int {
        return operatorMap[op]
    }

    applyOp := func(a int, b int, op string) int {
        switch op {
        case "+":
            return a + b
        case "-":
            return a - b
        case "*":
            return a * b
        case "//":
            if b != 0 {
                return a / b
            }
            return 0
        case "**":
            return int(math.Pow(float64(a), float64(b)))
        }
        return 0
    }

    var operators []string
    var operands []int

    for i := 0; i < len(operator); i++ {
        if len(operators) == 0 || precedence(operator[i]) > precedence(operators[len(operators)-1]) {
            operators = append(operators, operator[i])
            operands = append(operands, operand[i])
        } else {
            for len(operators) > 0 && precedence(operator[i]) <= precedence(operators[len(operators)-1]) {
                op := operators[len(operators)-1]
                operators = operators[:len(operators)-1]

                b := operands[len(operands)-1]
                operands = operands[:len(operands)-1]

                a := operands[len(operands)-1]
                operands = operands[:len(operands)-1]

                operands = append(operands, applyOp(a, b, op))
            }
            operators = append(operators, operator[i])
            operands = append(operands, operand[i])
        }
    }

    for len(operators) > 0 {
        op := operators[len(operators)-1]
        operators = operators[:len(operators)-1]

        b := operands[len(operands)-1]
        operands = operands[:len(operands)-1]

        a := operands[len(operands)-1]
        operands = operands[:len(operands)-1]

        operands = append(operands, applyOp(a, b, op))
    }

    return operands[0]
}

